                    @Configuration
    public class RBloomFilterConfiguration {
    ​
        /**
         * 优惠券查询缓存穿透布隆过滤器
         */
        @Bean
        public RBloomFilter<String> couponTemplateQueryBloomFilter(RedissonClient redissonClient, @Value("${framework.cache.redis.prefix:}") String cachePrefix) {
