             // 获取 LUA 脚本，并保存到 Hutool 的单例管理容器，下次直接获取不需要加载
             DefaultRedisScript<Void> buildLuaScript = Singleton.get(BATCH_SAVE_USER_COUPON_LUA_PATH, () -> {
